"""Opt-in economics helpers for relationship-sensitive cases; no agent activation.

A public should-cost estimate is uncertain, not a supplier reservation price. At fixed
non-price terms, buyer cost can fall when price rises because relationship cost falls.
Consequently an inverse must identify the increasing branch and reject infeasible caps.
These helpers choose arithmetic targets, not acceptance predictions or hard price floors.
"""

import itertools
import math

from arena_kit.cost import (
    RELATIONSHIP_GOALS,
    complete_offer,
    cost_breakdown,
    must_haves_ok,
    total_cost,
)


MAX_PRICE = 10_000_000.0


def active(case, supplier):
    buyer = case.get("buyer") or {}
    return bool(
        supplier and supplier.get("full_cost", 0) > 0
        and buyer.get("category_goal") in RELATIONSHIP_GOALS
        and buyer.get("relationship_eur_per_point", 0) > 0
        and buyer.get("sustainable_margin_pct", 0) > 0
    )


def _cost(case, terms, price, standard, supplier):
    # Search unrounded components: total_cost's cent rounding creates artificial plateaus.
    value = sum(cost_breakdown(case, {**terms, "unit_price": price}, standard, supplier).values())
    if not math.isfinite(value):
        raise ValueError("relationship search requires finite complete costs")
    return value


def min_price(case, terms, standard=None, supplier=None):
    """Cost-minimizing positive cent price for a fixed legal package.

    The kit cost is convex in price for fixed terms and positive supplier cash value.
    Grow the upper bound until increasing, then search the integer-cent grid. Invalid
    inputs fail explicitly instead of fabricating a usable price.
    """
    ref = terms.get("unit_price") or case["buyer"].get("current_unit_price") or 1.0
    hi = max(1.0, float(ref) * 2, float((supplier or {}).get("full_cost", 0)) * 2)
    if not math.isfinite(hi) or hi > MAX_PRICE:
        raise ValueError("invalid relationship search reference")

    def c(cents):
        return _cost(case, terms, cents / 100, standard, supplier)

    upper = math.ceil(hi * 100)
    while c(upper) > c(upper + 100):
        upper *= 2
        if upper > MAX_PRICE * 100:
            raise ValueError("could not bracket relationship cost minimum")
    lower = 1
    while upper - lower > 12:
        third = (upper - lower) // 3
        left, right = lower + third, upper - third
        if c(left) <= c(right):
            upper = right
        else:
            lower = left
    return min(range(lower, upper + 1), key=lambda p: (c(p), p)) / 100


def ceiling(case, terms, cap_c, standard=None, supplier=None):
    """Highest cent price costing at most cap_c, or None when no cent price qualifies.

    Search only above the minimum; never apply monotone bisection across the falling
    relationship-cost branch. cap_c uses the same rounded euros as total_cost.
    """
    if not math.isfinite(cap_c):
        raise ValueError("cost cap must be finite")
    lower = round(min_price(case, terms, standard, supplier) * 100)

    def c(cents):
        return total_cost(case, {**terms, "unit_price": cents / 100}, standard, supplier)

    if c(lower) > cap_c:
        return None
    upper = max(lower * 2, lower + 100)
    while c(upper) <= cap_c:
        upper *= 2
        if upper > MAX_PRICE * 100:
            raise ValueError("could not bracket relationship cost ceiling")
    while upper - lower > 1:
        mid = (lower + upper) // 2
        if c(mid) <= cap_c:
            lower = mid
        else:
            upper = mid
    return lower / 100


def targets(case, standard, supplier, reference=None):
    """All must-have-compliant option packages, each at its central-estimate minimum.

    Returns sorted (cost, terms) pairs. No implicit near-tie preference for financing
    terms and no exclusion of an allowed clause. Existing fixed terms remain fixed.
    """
    options = case.get("term_options") or {}
    fields = [f for f in case["negotiable"] if f != "unit_price" and options.get(f)]
    base = complete_offer(case, reference or {})
    out = []
    for values in itertools.product(*(options[f] for f in fields)):
        terms = {**base, **dict(zip(fields, values, strict=True))}
        terms["unit_price"] = terms.get("unit_price") or case["buyer"].get("current_unit_price") or 1.0
        if must_haves_ok(case, terms, standard):
            terms["unit_price"] = min_price(case, terms, standard, supplier)
            out.append((total_cost(case, terms, standard, supplier), terms))
    return sorted(out, key=lambda item: item[0])


def sensitivity(case, terms, standard, supplier):
    """Public low/central/high full-cost scenarios for ONE proposed package.

    Each row reports its cost and the scenario-optimal price for the same non-price
    package. The range is uncertainty, not observed supplier cost or a probability.
    """
    center = supplier["full_cost"]
    low, high = supplier.get("full_cost_range", (center, center))
    if not all(math.isfinite(v) and v > 0 for v in (low, center, high)) or not low <= center <= high:
        raise ValueError("invalid public supplier cost range")
    rows = []
    for label, full_cost in (("low", low), ("central", center), ("high", high)):
        scenario = {**supplier, "full_cost": full_cost}
        optimum = min_price(case, terms, standard, scenario)
        best_cost = total_cost(case, {**terms, "unit_price": optimum}, standard, scenario)
        proposed_cost = total_cost(case, terms, standard, scenario)
        rows.append({"scenario": label, "full_cost": full_cost, "optimal_price": optimum,
                     "optimal_cost": best_cost, "proposed_cost": proposed_cost,
                     "regret_same_package": round(proposed_cost - best_cost, 2)})
    return rows
